<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue';import {admin,money} from '../../../shared/api';import type {Page} from '../../../shared/types';import type {AdminPet} from '../../../shared/adminTypes';import {useLoad} from '../../../shared/useLoad';import {ElMessageBox,ElMessage} from 'element-plus'
const result=ref<Page<AdminPet>>(),query=reactive({keyword:'',status:'',category:''}),{loading,error,run}=useLoad();const statuses:Record<string,string>={off:'未上架',on_sale:'在售',reserved:'已预订',sold:'已售'}
const load=(page=1)=>run(async()=>{result.value=await admin('GET','/admin/pets',undefined,{...query,page,pageSize:10})})
async function unpublish(row:AdminPet){try{const {value}=await ElMessageBox.prompt('请填写下架原因','下架宠物',{inputValidator:v=>Boolean(v?.trim())||'请填写原因'});await run(async()=>{await admin('POST',`/admin/pets/${row.id}/unpublish`,{version:row.version,reason:value});ElMessage.success('已下架')});await load(result.value?.page)}catch{/* 用户取消对话框，不发起修改。 */}}
onMounted(()=>load())
</script>
<template><div class="section-title"><div><p class="eyebrow">PETS</p><h2>一宠一档，状态清晰。</h2></div><el-button type="primary" size="large" @click="$router.push('/pets/new')">＋ 发布宠物</el-button></div><form class="toolbar" @submit.prevent="load()"><el-input v-model="query.keyword" placeholder="名称 / 品种 / 编号" clearable aria-label="搜索宠物"/><el-select v-model="query.status" placeholder="全部状态" clearable @change="load()"><el-option v-for="(label,value) in statuses" :key="value" :value="value" :label="label"/></el-select><el-button native-type="submit" :loading="loading">查询</el-button></form><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="table-panel"><el-table :data="result?.items||[]" v-loading="loading"><el-table-column label="宠物 / 编号" min-width="240"><template #default="{row}"><div class="table-pet"><img v-if="row.assets?.[0]?.publicUrl" :src="row.assets[0].publicUrl" :alt="row.name"><div>{{row.name}}<small>{{row.id}}</small></div></div></template></el-table-column><el-table-column prop="breed" label="品种" min-width="150"/><el-table-column label="售价" min-width="130"><template #default="{row}">{{money(row.priceAmount)}}</template></el-table-column><el-table-column label="状态" min-width="110"><template #default="{row}"><el-tag :type="row.status==='on_sale'?'success':'info'">{{statuses[row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" width="190"><template #default="{row}"><el-button link type="primary" @click="$router.push(`/pets/${row.id}`)">{{['reserved','sold'].includes(row.status)?'查看档案':'编辑'}}</el-button><el-button v-if="row.status==='on_sale'" link @click="unpublish(row)">下架</el-button></template></el-table-column></el-table></div><div class="pagination"><el-pagination v-if="result" layout="prev, pager, next" :total="result.total" :page-size="10" :current-page="result.page" @current-change="load"/></div><p class="small muted">已预订和已售个体不能手动释放，状态由订单流程推进。</p></template>
